/* Graphite - generated by tools/build.mjs from src/scripts/web-recolor.js. Do not edit. */
/*
 * Graphite web recolor.
 *
 * Valve's newer React pages on store.steampowered.com / steamcommunity.com
 * (wishlist, calendar, news hub, charts, ...) hardcode their blue-grey
 * palette in CSS behind hashed class names that change with every deploy.
 * Instead of chasing those classes, this script looks at the *computed*
 * colors and swaps Valve's characteristic dark blue-greys for Graphite's
 * neutral surfaces (and Valve's bright blues for the accent).
 *
 * - Only touches colors that are clearly "Valve blue": a blue tint on a dark
 *   surface, or Steam's link/button blues. Images, game art, rarity colors,
 *   greens, reds and the Graphite colors themselves are left alone.
 * - Runs once on load and then only on newly added DOM subtrees, batched
 *   into idle time.
 * - Fully local; no network access.
 * - Also tags the parts of a few redesigned React pages (wishlist) with
 *   stable gr-* classes for the theme CSS; see "Structure hooks".
 */
(() => {
	if (window.__graphiteRecolor) return;
	window.__graphiteRecolor = true;

	const DONE = 'grRecolored';
	const applied = new WeakMap(); // element -> properties we set

	const parse = s => {
		const m = s && s.match(/rgba?\(\s*([\d.]+)[ ,]+([\d.]+)[ ,]+([\d.]+)(?:[ ,/]+([\d.]+))?/);
		return m ? { r: +m[1], g: +m[2], b: +m[3], a: m[4] === undefined ? 1 : +m[4] } : null;
	};
	const lum = c => (0.2126 * c.r + 0.7152 * c.g + 0.0722 * c.b) / 255;

	// "Valve blue-grey": dark-ish, blue clearly above red, not a saturated hue
	const isSurfaceBlue = c => c.b > 20 && c.b - c.r >= 10 && c.b >= c.g && lum(c) < 0.42 && c.b - c.r < 90;
	// bright Steam blues used for links / primary buttons / highlights
	const isBrightBlue = c => c.b > 180 && c.b - c.r > 90 && lum(c) > 0.3;

	const surface = l => (l < 0.075 ? '--gr-bg' : l < 0.115 ? '--gr-surface' : l < 0.17 ? '--gr-surface-2' : '--gr-surface-3');
	const alpha = (v, a) => (a >= 0.99 ? `var(${v})` : `color-mix(in srgb, var(${v}) ${Math.round(a * 100)}%, transparent)`);

	// legacy store markup that web-app.css restyles completely: never paint
	// surfaces or accent buttons there, only fix link text colors
	const OWN = [
		'.game_page_background_ctn', '.game_background_lighten', '.queue_actions_ctn',
		'.game_purchase_action', '#category_block', '.details_block',
		'.recommendation_noinfo', '#shareEmbedRow', '.sysreq_tabs', '.game_area_play_stats',
		'.game_area_already_owned', '.game_area_purchase_not_refundable',
		'.steam_curators_block .block_header',
		// search page: filter column and result rows (web-search.css)
		'#additional_search_options', '#search_resultsRows', '.searchbar'
	].join(',');

	function recolor(el) {
		if (el.dataset && el.dataset[DONE]) return;
		const cs = getComputedStyle(el);
		const set = [];
		if (el.closest && el.closest(OWN)) {
			textColor(el, cs, set);
			for (const [p, v] of set) el.style.setProperty(p, v, 'important');
			if (set.length) applied.set(el, set.map(([p]) => p));
			if (el.dataset) el.dataset[DONE] = '1';
			return;
		}
		// parts restyled by Graphite's own CSS (see hooks below): leave their
		// surfaces alone, only fix text colors
		const hooked = !!(el.closest && el.closest('[data-gr-hook]'));
		if (hooked) {
			// bright Steam-blue buttons still become accent buttons
			const hb = parse(cs.backgroundColor);
			if (hb && hb.a > 0.05 && isBrightBlue(hb)) set.push(['background-color', 'var(--gr-accent)'], ['color', 'var(--gr-bg)']);
			const himg = cs.backgroundImage;
			if (himg && himg.includes('gradient') && !himg.includes('url(') && [...himg.matchAll(/rgba?\([^)]+\)/g)].map(m => parse(m[0])).some(c => c && isBrightBlue(c))) {
				set.push(['background-image', 'none'], ['background-color', 'var(--gr-accent)'], ['color', 'var(--gr-bg)']);
			}
			textColor(el, cs, set);
			for (const [p, v] of set) el.style.setProperty(p, v, 'important');
			if (set.length) applied.set(el, set.map(([p]) => p));
			if (el.dataset) el.dataset[DONE] = '1';
			return;
		}

		const bg = parse(cs.backgroundColor);
		if (bg && bg.a > 0.05) {
			if (isSurfaceBlue(bg)) set.push(['background-color', alpha(surface(lum(bg)), bg.a)]);
			else if (isBrightBlue(bg)) set.push(['background-color', 'var(--gr-accent)'], ['color', 'var(--gr-bg)']);
		}

		const img = cs.backgroundImage;
		if (img && img !== 'none' && !img.includes('url(') && img.includes('gradient')) {
			const stops = [...img.matchAll(/rgba?\([^)]+\)/g)].map(m => parse(m[0])).filter(Boolean);
			const blue = stops.filter(c => c.a > 0.05 && (isSurfaceBlue(c) || isBrightBlue(c)));
			if (blue.length && blue.length >= stops.filter(c => c.a > 0.05).length / 2) {
				set.push(['background-image', 'none']);
				const opaque = stops.filter(c => c.a > 0.5);
				if (opaque.length) {
					const avg = opaque.reduce((s, c) => s + lum(c), 0) / opaque.length;
					if (opaque.some(isBrightBlue)) set.push(['background-color', 'var(--gr-accent)'], ['color', 'var(--gr-bg)']);
					else set.push(['background-color', `var(${surface(avg)})`]);
				}
			}
		}

		for (const side of ['top', 'right', 'bottom', 'left']) {
			if (cs[`border-${side}-style`] === 'none' || cs[`border-${side}-width`] === '0px') continue;
			const c = parse(cs[`border-${side}-color`]);
			if (c && c.a > 0.05 && (isSurfaceBlue(c) || isBrightBlue(c))) set.push([`border-${side}-color`, 'var(--gr-border)']);
		}

		textColor(el, cs, set);

		for (const [p, v] of set) el.style.setProperty(p, v, 'important');
		if (set.length) applied.set(el, set.map(([p]) => p));
		if (el.dataset) el.dataset[DONE] = '1';
	}

	// light-blue link / label text -> accent (only leaf-ish text elements)
	function textColor(el, cs, set) {
		if (set.some(([p]) => p === 'color') || el.childElementCount > 1) return;
		const t = parse(cs.color);
		if (t && t.b > 170 && t.b - t.r > 60 && lum(t) > 0.35) set.push(['color', 'var(--gr-accent)']);
	}

	/*
	 * Structure hooks. Some React pages are worth a real redesign, but their
	 * class names are hashed and change with every store deploy. So the
	 * parts are found by structure (links, inputs, buttons) and tagged with
	 * stable gr-* classes that the theme CSS styles (web-wishlist.css).
	 */
	const unrecolor = root => {
		for (const el of [root, ...root.querySelectorAll('*')]) {
			const props = applied.get(el);
			if (props) { props.forEach(p => el.style.removeProperty(p)); applied.delete(el); }
			if (el.dataset) delete el.dataset[DONE];
		}
	};
	const hook = (el, cls) => {
		if (!el || el.classList.contains(cls)) return;
		el.classList.add(cls);
		if (!el.closest('[data-gr-hook]')) { el.dataset.grHook = ''; unrecolor(el); }
	};
	const leaves = root => [...root.querySelectorAll('*')].filter(e => !e.children.length && !(e instanceof SVGElement));

	const ROLES = ['gr-wl-rank', 'gr-wl-name', 'gr-wl-buy', 'gr-wl-added', 'gr-wl-cats', 'gr-wl-info'];
	function hookWishlist() {
		if (!/^\/wishlist\//.test(location.pathname)) return;
		document.documentElement.classList.add('gr-wishlist');

		// page header and toolbar
		const search = [...document.querySelectorAll('input[placeholder]')]
			.find(i => i.type === 'text' && !i.closest('form') && i.getBoundingClientRect().width > 300); // (the store search is a form)
		if (search) {
			const bar = search.parentElement;
			hook(bar, 'gr-wl-toolbar');
			const count = bar.nextElementSibling;
			if (count && !count.querySelector('a, input')) hook(count, 'gr-wl-count');
			const head = bar.previousElementSibling;
			if (head && head.querySelector('h2')) {
				hook(head, 'gr-wl-head');
				// Valve writes the heading in capitals; the page title has the
				// same words in normal case, so CSS shows that instead (the
				// React-owned text node itself stays untouched)
				const h2 = head.querySelector('h2');
				const title = document.title.replace(/\s*::.*$/, '').trim();
				if (title && h2.textContent.trim().toUpperCase() === title.toUpperCase()) h2.dataset.grTitle = title;
			}
		}

		// one card per wishlist entry: the capsule link (with image) sits
		// directly in the card, next to title, details, price and "added"
		for (const cap of document.querySelectorAll('a[href*="/app/"]')) {
			if (!cap.querySelector('img')) continue;
			const row = cap.parentElement;
			// (re-run on every pass: React fills cards in over several renders)
			if (!row || row.getBoundingClientRect().width < 600) continue;
			hook(row, 'gr-wl-row');
			if (!cap.classList.contains('gr-wl-cap')) cap.classList.add('gr-wl-cap');
			// work out each part's role first, then only touch classes that
			// actually change (re-adding them would restart CSS transitions)
			const role = new Map();
			const rest = [];
			for (const c of row.children) {
				if (c === cap || c.tagName === 'DIALOG') continue;
				const app = c.querySelector('a[href*="/app/"]');
				const btn = c.querySelector('button');
				if (c.querySelector('input') && !app) role.set(c, 'gr-wl-rank');
				else if (app && !btn) role.set(c, 'gr-wl-name');
				else if (app && btn) role.set(c, 'gr-wl-buy');
				else rest.push(c);
			}
			// remaining: "added on / remove" (top right), categories, details
			const rr = row.getBoundingClientRect();
			const added = rest.find(c => { const r = c.getBoundingClientRect(); return r.top - rr.top < 30 && rr.right - r.right < 40; });
			if (added) role.set(added, 'gr-wl-added');
			// details = the block with the tag buttons (or, without tags, the
			// one with the most text); categories = the top block with one button
			const others = rest.filter(c => c !== added && c.textContent.trim());
			const score = c => c.querySelectorAll('button').length * 100 + c.textContent.length;
			const info = others.slice().sort((x, y) => score(y) - score(x))[0];
			if (info) role.set(info, 'gr-wl-info');
			const cats = others.filter(c => c !== info && c.querySelectorAll('button').length === 1)
				.sort((x, y) => x.getBoundingClientRect().top - y.getBoundingClientRect().top)[0];
			if (cats) role.set(cats, 'gr-wl-cats');
			for (const c of row.children) {
				if (c === cap) continue;
				const want = role.get(c);
				for (const k of ROLES) if (k !== want && c.classList.contains(k)) c.classList.remove(k);
				if (want && !c.classList.contains(want)) c.classList.add(want);
			}
			for (const l of leaves(row)) if (/:\s*$/.test(l.textContent) && !l.classList.contains('gr-wl-label')) l.classList.add('gr-wl-label');
			if (info) info.querySelectorAll('button:not(.gr-wl-tag)').forEach(t => t.classList.add('gr-wl-tag'));
			const buy = row.querySelector('.gr-wl-buy');
			if (buy) buy.querySelectorAll('button:not(.gr-wl-cart)').forEach(t => t.classList.add('gr-wl-cart'));
		}
	}

	// news hub (store.steampowered.com/news): sidebar, date sections, cards
	const addCls = (el, c) => { if (el && !el.classList.contains(c)) el.classList.add(c); };
	function hookNewsHub() {
		if (!document.body || !document.body.classList.contains('events_hub')) return;
		addCls(document.documentElement, 'gr-newshub');
		const root = document.querySelector('.page_content_ctn > div > div > .Panel');
		if (!root || root.children.length < 2) return;
		const side = root.children[0], main = root.children[root.children.length - 1];
		hook(side, 'gr-nh-side');
		hook(main, 'gr-nh-main');
		for (const el of side.querySelectorAll('div')) {
			const cs = getComputedStyle(el);
			const r = el.getBoundingClientRect();
			if (el.classList.contains('gr-nh-title')) continue;
			if (parseFloat(cs.fontSize) >= 28 && el.textContent.trim()) addCls(el, 'gr-nh-title');
			else if (r.width >= 380 && r.height >= 380) addCls(el, 'gr-nh-mark');
			else if (!el.querySelector('a') && el.nextElementSibling && el.nextElementSibling.querySelector('a')) addCls(el, 'gr-nh-label');
		}
		side.querySelectorAll('a').forEach(a => addCls(a, 'gr-nh-link'));
		// date sections: a 24px uppercase heading followed by entries
		for (const head of main.querySelectorAll('div')) {
			if (head.classList.contains('gr-nh-sechead')) continue;
			const cs = getComputedStyle(head);
			if (cs.textTransform !== 'uppercase' || parseFloat(cs.fontSize) < 20 || !head.parentElement) continue;
			if (head.parentElement.firstElementChild !== head) continue;
			addCls(head, 'gr-nh-sechead');
			hook(head.parentElement, 'gr-nh-section');
		}
		for (const sec of main.querySelectorAll('.gr-nh-section')) {
			for (const item of sec.children) {
				if (item.classList.contains('gr-nh-sechead')) continue;
				addCls(item, 'gr-nh-item');
				const card = item.querySelector('a');
				if (card) addCls(card, 'gr-nh-card');
				for (const d of item.querySelectorAll('div')) {
					if (d.children.length > 1 || !d.textContent.trim()) continue;
					if (parseFloat(getComputedStyle(d).fontSize) >= 20) addCls(d, 'gr-nh-headline');
				}
			}
		}
	}

	// event detail overlay (news / patch notes) on store and community pages
	function hookEventModal() {
		const root = document.querySelector('.FullModalOverlay .ModalOverlayContent.active');
		if (!root) return;
		const banner = root.querySelector('.AppPartnerEventsBanner');
		if (banner) hook(banner, 'gr-ev-banner');
		for (const a of root.querySelectorAll('a')) {
			if (a.classList.contains('gr-ev-title') || parseFloat(getComputedStyle(a).fontSize) < 20) continue;
			let card = a.parentElement;
			while (card && card !== root && !(card.getBoundingClientRect().width >= 600 && getComputedStyle(card).backgroundColor !== 'rgba(0, 0, 0, 0)')) card = card.parentElement;
			if (!card || card === root) continue;
			addCls(a, 'gr-ev-title');
			hook(card, 'gr-ev-card');
			addCls(card.firstElementChild, 'gr-ev-head');
			if (card.children.length > 2) addCls(card.lastElementChild, 'gr-ev-foot');
		}
		// round close button and the up / down / app buttons next to the card
		for (const b of root.querySelectorAll('div')) {
			if (b.classList.contains('gr-ev-navbtn')) continue;
			const r = b.getBoundingClientRect();
			if (r.width !== 50 || r.height < 25 || r.height > 50) continue;
			if (getComputedStyle(b).backgroundColor === 'rgba(0, 0, 0, 0)') continue;
			hook(b, 'gr-ev-navbtn');
		}
	}

	// store front: personal calendar day columns get Graphite surfaces from CSS
	function hookStoreHome() {
		for (const day of document.querySelectorAll('.personal_calendar_ctn .carousel__inner-slide > div')) {
			if (!day.classList.contains('gr-cal-day')) hook(day, 'gr-cal-day');
		}
	}

	// store navigation search button: Valve paints it bright blue on some pages
	function hookStoreNav() {
		if (location.hostname !== 'store.steampowered.com') return;
		for (const b of document.querySelectorAll('button')) {
			if (b.classList.contains('gr-navsearch')) continue;
			const r = b.getBoundingClientRect();
			if (r.top > 70 || r.height === 0 || r.width > 60) continue;
			const bg = parse(getComputedStyle(b).backgroundColor);
			if (bg && isBrightBlue(bg)) hook(b, 'gr-navsearch');
		}
	}

	// game page: React parts inside the legacy layout (shelves, side widgets,
	// user reviews) get gr-app-* / gr-rv-* classes; web-app.css styles them
	let appCount = -1;
	function hookAppPage() {
		if (!document.body.classList.contains('app') || location.hostname !== 'store.steampowered.com') return;
		const scope = document.querySelector('.page_content_ctn');
		if (!scope) return;
		const n = scope.getElementsByTagName('div').length;
		if (n === appCount) return; // nothing new rendered
		appCount = n;
		for (const p of document.querySelectorAll('.related_items_ctn > .page_content > div:not([class]) > div > .Panel')) hook(p, 'gr-app-shelf');
		for (const side of document.querySelectorAll('.rightcol.game_meta_data > div:not([class]):not([id])')) {
			for (const e of side.querySelectorAll('div')) {
				if (e.classList.contains('gr-app-side')) continue;
				if (getComputedStyle(e).backgroundImage.startsWith('linear-gradient') && e.getBoundingClientRect().width > 300) hook(e, 'gr-app-side');
			}
		}
		const rv = document.getElementById('app_reviews_hash');
		if (!rv) return;
		for (const e of rv.querySelectorAll('div')) {
			if (e.matches('.gr-rv-card, .gr-rv-head, .gr-rv-bar, .gr-rv-sum')) continue;
			const cs = getComputedStyle(e);
			if (cs.backgroundImage.startsWith('radial-gradient')) { hook(e, 'gr-rv-sum'); continue; }
			if (cs.backgroundColor !== 'rgba(0, 0, 0, 0.2)') continue;
			const r = e.getBoundingClientRect();
			if (r.width > 1000) hook(e, r.height > 80 ? 'gr-rv-card' : 'gr-rv-bar');
			else if (r.width > 500 && r.height < 70) hook(e, 'gr-rv-head');
		}
	}

	const queue = new Set();
	let scheduled = false;
	const idle = window.requestIdleCallback || (fn => setTimeout(() => fn({ timeRemaining: () => 8 }), 50));

	function flush(deadline) {
		scheduled = false;
		try { hookWishlist(); hookStoreNav(); hookNewsHub(); hookEventModal(); hookStoreHome(); hookAppPage(); } catch (e) { /* never break the page */ }
		for (const root of queue) {
			queue.delete(root);
			if (!root.isConnected) continue;
			recolor(root);
			for (const el of root.querySelectorAll('*')) {
				if (el instanceof SVGElement || el.tagName === 'IMG' || el.tagName === 'VIDEO' || el.tagName === 'CANVAS') continue;
				recolor(el);
			}
			if (deadline.timeRemaining() < 2) break;
		}
		if (queue.size) schedule();
	}
	function schedule() {
		if (!scheduled) { scheduled = true; idle(flush); }
	}
	function add(node) {
		if (node.nodeType === 1) { queue.add(node); schedule(); }
	}

	function start() {
		add(document.body);
		new MutationObserver(muts => {
			for (const m of muts) {
				if (m.type === 'childList') m.addedNodes.forEach(add);
				else if (m.type === 'attributes' && m.target.dataset) {
					// class change (selected / active state): drop our overrides so the
					// page's real color for the new state is visible, then re-evaluate
					const props = applied.get(m.target);
					if (props) { props.forEach(p => m.target.style.removeProperty(p)); applied.delete(m.target); }
					delete m.target.dataset[DONE];
					queue.add(m.target); schedule();
				}
			}
		}).observe(document.body, { childList: true, subtree: true, attributes: true, attributeFilter: ['class'] });
	}

	if (document.body) start();
	else document.addEventListener('DOMContentLoaded', start, { once: true });
})();

/*
 * "Special offers" popup (store.steampowered.com/marketingmessages/...), the
 * window Steam opens at start: Steam-grey backdrop, a big blurred copy of the
 * image, blue-grey dots. Its React classes are hashed, so the parts are found
 * by structure and marked with data-gr-mm.
 */
(() => {
	if (location.hostname !== 'store.steampowered.com' || !location.pathname.startsWith('/marketingmessages')) return;
	const css = `
		html, body { background: var(--gr-bg) !important; }
		[data-gr-mm="root"] { background: var(--gr-bg) !important; }
		/* the blurred copy behind the image: a soft glow instead of a smear */
		[data-gr-mm="glow"] { opacity: .28 !important; filter: blur(48px) saturate(1.2) !important; }
		[data-gr-mm="art"] { border-radius: 14px !important; overflow: hidden !important; box-shadow: 0 24px 60px rgba(0,0,0,.55) !important; }
		[data-gr-mm="cta"] { border-radius: var(--gr-radius) !important; background: var(--gr-surface-2) !important; border: 1px solid var(--gr-border) !important; }
		[data-gr-mm="nav"] { border-top: 0 !important; }
		[data-gr-mm="arrow"] { border-radius: 50% !important; transition: background .15s ease, opacity .15s ease !important; }
		[data-gr-mm="arrow"]:hover { background: var(--gr-hover) !important; }
		[data-gr-mm="arrow"] svg path, [data-gr-mm="arrow"] svg polyline { stroke: var(--gr-text-2) !important; fill: none; }
		[data-gr-mm="arrow"] svg polygon { fill: var(--gr-text-2) !important; }
		[data-gr-mm="dot"] { border-radius: 3px !important; background: var(--gr-text-3) !important; transition: width .2s ease, background .2s ease !important; }
		[data-gr-mm="dot"].gr-on { background: var(--gr-text) !important; }
	`;
	const mark = (el, v) => { if (el && el.dataset.grMm !== v) el.dataset.grMm = v; };
	function run() {
		const app = document.getElementById('application_root');
		if (!app) return;
		const root = [...app.querySelectorAll('div')].find((e) => {
			const r = e.getBoundingClientRect();
			return r.width >= innerWidth - 2 && r.height >= innerHeight - 2 && getComputedStyle(e).backgroundColor !== 'rgba(0, 0, 0, 0)';
		});
		if (!root) return;
		mark(root, 'root');
		for (const d of root.querySelectorAll('div')) {
			const cs = getComputedStyle(d);
			if (/blur/.test(cs.filter) && d.querySelector('img')) { mark(d, 'glow'); continue; }
			const img = d.firstElementChild;
			if (img && img.tagName === 'IMG' && d.children.length === 1 && !/blur/.test(getComputedStyle(d.parentElement).filter) && d.getBoundingClientRect().width > 200) mark(d, 'art');
		}
		// the bar under the image (call to action)
		for (const p of root.querySelectorAll('.Panel')) {
			if (p.dataset.grMm || p.querySelector('img')) continue;
			const r = p.getBoundingClientRect();
			if (r.height > 30 && r.height < 70 && r.width > 200 && getComputedStyle(p).backgroundColor !== 'rgba(0, 0, 0, 0)') mark(p, 'cta');
		}
		// bottom navigation: two arrow boxes with an svg, small dot bars between
		const svgs = [...root.querySelectorAll('svg')].filter((s) => s.getBoundingClientRect().top > innerHeight - 140);
		for (const s of svgs) mark(s.parentElement, 'arrow');
		if (svgs[0]) mark(svgs[0].parentElement.parentElement.parentElement, 'nav');
		const dots = [...root.querySelectorAll('div')].filter((e) => {
			const r = e.getBoundingClientRect();
			return !e.children.length && r.height > 2 && r.height < 9 && r.width > 6 && r.width < 30 && r.top > innerHeight - 140;
		});
		for (const d of dots) {
			mark(d, 'dot');
			// the active dot is the white one Steam draws
			const on = /255, 255, 255/.test(d.style.backgroundColor) || d.className.split(' ').length > 1;
			d.classList.toggle('gr-on', on);
		}
	}
	let queued = false;
	const start = () => {
		const st = document.createElement('style');
		st.id = 'gr-mm-css';
		st.textContent = css;
		document.head.append(st);
		run();
		new MutationObserver(() => {
			if (queued) return;
			queued = true;
			setTimeout(() => { queued = false; run(); }, 120);
		}).observe(document.body, { childList: true, subtree: true, attributes: true, attributeFilter: ['class'] });
		addEventListener('resize', run);
	};
	if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start, { once: true });
	else start();
})();

